export type Args = Record<string, unknown>;

/**
 * Whether the effect of a command is finished when it is accepted. `completed`: the recorded change is the effect (a task changes state). `deferred`: the command is durably accepted
 * and announced, and something else (a worker) must act before the work is done; the result says what to look at.
 */
export type Completion = { readonly kind: "completed" } | { readonly kind: "deferred"; readonly awaits: string };

/** What the API needs to revoke a catalogue version: the one shared catalogue and the calls the tool bridge is running. */
export interface CatalogRevocationPort {
  revoke(owner: Principal, command: { commandId: string; name: string; version: string; reason: string; runningCalls?: "finish" | "cancel" | "pause" }): Promise<void>;
  /** Past revocations, newest first (card T02c). */
  revocations(owner: Principal, query: { name?: string; limit?: number }): Promise<{ readonly items: readonly { name: string; version: string; reason: string; revokedBy: string; at: string }[]; readonly total: number; readonly partial?: boolean }>;
  /** The calls listed (capped) and how many are running in all, so a caller can say "N running calls" when the list is cut. */
  running(owner: Principal, name: string, version: string): Promise<{ readonly calls: readonly { readonly attemptId: string; readonly callId: string; readonly taskId: string; readonly agentId: string }[]; readonly total: number }>;
}

export interface Operation {
  readonly name: string;
  readonly kind: "query" | "command";
  readonly summary: string;
  /** Argument names with a plain description; a trailing `?` marks an optional one. */
  readonly args: Readonly<Record<string, string>>;
  readonly result: string;
  readonly completion?: Completion;
  readonly run: (context: Context, args: Args, commandId: string | undefined) => Promise<JsonObject>;
}

export const PAGE = { default: 20, max: 100 } as const;

const invalid = (field: string, message: string): never => { throw new DomainError("invalid_command", `${field}: ${message}`, { field }); };

function only(args: Args, known: readonly string[]): void {
  for (const key of Object.keys(args)) if (!known.includes(key)) invalid(`args.${key}`, "is not an argument of this operation");
}
function str(args: Args, key: string): string {
  const v = args[key];
  return typeof v === "string" ? v : invalid(`args.${key}`, "is required and must be text");
}
function optStr(args: Args, key: string): string | undefined {
  const v = args[key];
  return v === undefined ? undefined : (typeof v === "string" ? v : invalid(`args.${key}`, "must be text"));
}
function limitOf(args: Args): number {
  const v = args["limit"];
  if (v === undefined) return PAGE.default;
  return typeof v === "number" && Number.isSafeInteger(v) && v >= 1 && v <= PAGE.max ? v : invalid("args.limit", `must be a whole number from 1 to ${PAGE.max}`);
}
/** A task credential acts for its one task: it may not read the failed event queue, which spans tasks and carries text from outside. */
const notFromTask = (c: Context, what: string): void => { if (c.principal.taskScope !== undefined) throw new DomainError("forbidden", `a task credential may not ${what}`); };
/** A task credential reads the activity of its own task only: another task's record (a sibling's) is out of reach, whatever else the credential holds. */
const ownTaskOnly = (c: Context, taskId: unknown, what: string): void => { if (c.principal.taskScope !== undefined && c.principal.taskScope.taskId !== taskId) throw new DomainError("forbidden", `a task credential may not ${what}`); };
const watches = (c: Context): WatchService => c.watches ?? ((): never => { throw new DomainError("unavailable", "event handling is not configured"); })();
/** What the owner is told of a finished move or rollback, in plain lines (the chat shows them): where the controller database is now, and what happens next. */
function transferShown(what: "moved" | "rolled back", item: { to: string; restart: string; replayed?: true }): string[] {
  const next = item.restart === "scheduled" ? "The host restarts the controller onto it in a moment." : item.restart === "off" ? "The automatic restart is off: restart the controller yourself." : "Restart the controller to go on; until then it waits.";
  return [`${item.replayed === true ? "This was already done: the database was " : "The database was "}${what} to ${item.to}. ${next}`];
}
const ownerOnly = (c: Context, what: string): void => { if (c.principal.kind !== "owner") throw new DomainError("forbidden", `${c.principal.id} may not ${what}`); };
const backupItem = (m: { name: string; createdAt: string; kind: string; schemaVersion: number; epoch: number; files: readonly { rows: number }[]; piState?: { problemCount?: number } }) => ({ name: m.name, createdAt: m.createdAt, kind: m.kind, schemaVersion: m.schemaVersion, epoch: m.epoch, rows: m.files.reduce((n, f) => n + f.rows, 0), piState: m.piState === undefined ? "not included" : (m.piState.problemCount ?? 0) > 0 ? `included, ${m.piState.problemCount} problem(s)` : "included" });
const unavailable = (what: string): never => { throw new DomainError("unavailable", `${what} is not configured`); };
const resources = (c: Context): ProjectResourceService => c.resources ?? unavailable("project resources");
const plans = (c: Context): ProjectPlanService => c.plans ?? unavailable("project plans");
const ownerQuestionsOf = (c: Context): NonNullable<Context["ownerQuestions"]> => c.ownerQuestions ?? unavailable("questions to the owner");
const branchesOf = (c: Context): ContextBranchService => c.branches ?? unavailable("context branches");
const notesOf = (c: Context): NonNullable<Context["notes"]> => c.notes ?? unavailable("working notes");
const pausesOf = (c: Context): NonNullable<Context["pauses"]> => c.pauses ?? unavailable("pause");
const jobsOf = (c: Context): NonNullable<Context["jobs"]> => c.jobs ?? unavailable("jobs");
/** A job the caller may read, and, for a task credential, only one of its own task (card T07b: a job started under one task's grants is never read or controlled from another task). */
const jobOf = async (c: Context, jobId: unknown): Promise<View<JobBody>> => {
  if (typeof jobId !== "string") return invalid("args.jobId", "is required and must be a job ID");
  const job = await jobsOf(c).get(c.principal, jobId);
  if (job === undefined || (c.principal.taskScope !== undefined && c.principal.taskScope.taskId !== job.taskId)) throw new DomainError("not_found", "no such job");
  return job;
};
/** What a job record says, as the API shows it (the output's end is the redacted text the record keeps). */
const jobItem = (job: View<JobBody>): JsonObject => asJson(job);
const modelBudgetOf = (c: Context): NonNullable<Context["modelBudget"]> => c.modelBudget ?? unavailable("model budgets");
const cutoverOf = (c: Context): NonNullable<Context["cutover"]> => c.cutover ?? unavailable("provider drain and cutover");
