/** The owner decision recorded for the meeting decision and never linked to it, in plain words (card M02h). */
const orphanLines = (out: Readonly<Record<string, unknown>>): string[] => {
  const list = Array.isArray(out["orphanedDecisions"]) ? (out["orphanedDecisions"] as { id?: unknown; topic?: unknown; state?: unknown }[]) : [];
  return list.flatMap((o) => {
    if (typeof o.id !== "string" || typeof o.topic !== "string") return [];
    const state = o.state === "active" ? "is in force" : o.state === "disputed" ? "conflicts with another of your instructions, so nothing on that topic is in force until you choose" : "has since been replaced";
    const hint = o.state === "active" ? ` If it should not stand, say what you decide on topic "${o.topic}" now (a later decision of yours replaces it).` : o.state === "disputed" ? " Settle that conflict to choose." : "";
    return [`Your earlier decision ${o.id} on topic "${o.topic}" was recorded for this meeting decision but is not linked to this answer, and ${state}.${hint}`];
  });
};
const DISPUTED_LINE = "Your decision is recorded, but it conflicts with another of your instructions on its topic: nothing on that topic is in force until you choose.";
/** What an owner's answer did, in plain lines, from the counts `ownerRespond` returns (card M02h): what was carried out now, what was not and why, what was done before, what is still open. */
export function ownerAnswerLines(response: string, out: Readonly<Record<string, unknown>>): string[] {
  const num = (k: string): number => (typeof out[k] === "number" ? (out[k] as number) : 0);
  const count = (k: number): string => `${k} change${k === 1 ? "" : "s"}`;
  const given = `This answer (${response === "agree" ? "agree" : response === "decline" ? "decline" : "your own decision"}) was already given`;
  const replayed = out["replayed"] === true;
  // A repeat still finishes what an earlier call left started: it says "nothing more was done" only when that is true.
  if (replayed && num("carriedOut") === 0 && (!Array.isArray(out["refused"]) || out["refused"].length === 0) && out["stillApplying"] !== true && out["passFailed"] !== true) return [`${given}; nothing more was done now.`, ...(out["ownerDecisionDisputed"] === true ? [DISPUTED_LINE] : []), ...orphanLines(out)];
  const carried = num("carriedOut");
  const before = num("alreadyDone");
  const refused = Array.isArray(out["refused"]) ? (out["refused"] as string[]) : [];
  // "Finished what was left" only when nothing is left; a repeat that moved things on but stopped says how far it got.
  const lines: string[] = replayed ? [`${given}; ${carried > 0 || refused.length > 0 ? (num("stillOpen") === 0 ? "this call finished what was left" : "this call did this much of what was left") : "what was left could not be finished now"}:`] : [];
  const refusedBefore = num("refusedBefore");
  const byCode = new Map<string, number>();
  for (const code of refused) if (!(response !== "agree" && code === "owner")) byCode.set(code, (byCode.get(code) ?? 0) + 1);
  if (response === "agree") lines.push(`You agreed.${carried > 0 ? ` ${count(carried)} carried out now.` : " None of its changes was carried out now."}${before > 0 ? ` ${count(before)} had been done before.` : ""}${refusedBefore > 0 ? ` ${count(refusedBefore)} had been refused before.` : ""}`);
  else {
    lines.push(response === "decline" ? "You declined. The changes not yet started are refused; those already done stay done." : `You chose your own decision instead${typeof out["ownerDecisionId"] === "string" ? ` (${out["ownerDecisionId"]})` : ""}. The changes not yet started are refused; those already done stay done.`);
    if (carried > 0) lines.push(`${count(carried)} already started ${carried === 1 ? "was" : "were"} finished.`);
    if (refusedBefore > 0) lines.push(`${count(refusedBefore)} had been refused before.`);
  }
  for (const [code, n] of byCode) lines.push(`${count(n)} not carried out: ${NOT_CARRIED_OUT[code] ?? "it could not be carried out"}.`);
  const applying = num("applying");
  const others = Math.max(0, num("stillOpen") - applying);
  if (out["stillApplying"] === true) {
    lines.push(`${count(applying)} started but could not be carried out just now and ${applying === 1 ? "stays" : "stay"} applying. Nothing applies ${applying === 1 ? "it" : "them"} again by itself: ${applying === 1 ? "it is" : "they are"} finished when the decision is applied again through the API (meeting.record.apply); you have no chat command for that yet.`);
    if (others > 0) lines.push(`${others} more change${others === 1 ? "" : "s"} still ${others === 1 ? "waits" : "wait"} to be carried out.`);
  } else if (out["passFailed"] === true && carried > 0) {
    lines.push(`Carrying out stopped before the rest started; ${count(num("stillOpen"))} still ${num("stillOpen") === 1 ? "waits" : "wait"}. Nothing applies ${num("stillOpen") === 1 ? "it" : "them"} again by itself; the decision must be applied again through the API (meeting.record.apply), which you have no chat command for yet.`);
  } else if (out["passFailed"] === true) {
    lines.push(`Carrying out the changes failed before ${before > 0 || refusedBefore > 0 || refused.length > 0 ? "any of the remaining changes" : "any of them"} started; ${count(num("stillOpen"))} still ${num("stillOpen") === 1 ? "waits" : "wait"}. Nothing applies ${num("stillOpen") === 1 ? "it" : "them"} again by itself; the decision must be applied again through the API (meeting.record.apply), which you have no chat command for yet.`);
  } else if (response === "agree" && num("stillOpen") > 0) lines.push(`${count(num("stillOpen"))} still ${num("stillOpen") === 1 ? "waits" : "wait"} to be carried out.`);
  if (out["ownerDecisionDisputed"] === true) lines.push(DISPUTED_LINE);
  lines.push(...orphanLines(out));
  return lines;
}

